六、合同总价及支付方式
1、合同暂定总价为人民币 281.6 万元（大写：贰佰捌拾壹万陆仟元整）；
2、支付方式：现金或银行转账结算；第一笔款项：合同签订三日内预付 30%工程款；第二笔款项：主材进场后经甲方验收确认规格型号、数量、外观质量等无异议后，三个工作内支付合同总价的 30%工程款；第三笔款项：在光伏系统并网发电三个工作日内支付至实际安装总容量金额的 95%；剩余 5%作为质保金。一兆瓦年发电量约 80 万度，上下浮动不超过百分之五；线性输出功率按厂家公式为准。发电质量保证期为 12 个月，自甲方出具书面验收报告之次日起开始计算；质保期内无重大质量问题（维修次数不超过三次或更换零件不超过 3%视为无重大质量问题），质保期届满后 10 日内向乙方支付质保金。
七、本发电工程所使用的光伏组件采用通威 TOP CON N 型 585-615W 单晶硅组件，逆变器华为，所用电缆采用铜芯国标电缆。
八、光伏项目的电网接入采用自发自用、余电上网方式（光伏发电优先供给企业使用，多余电量直接出售给国家电网，不足部分企业直接从国家电网购买）。
九、乙方提供的光伏组件效率应符合国家认证标准，且单块组件功率不低于 550 瓦，使用年限二十五年，总衰竭不超过百分之二十。若超过百分之二十，', '0', 'ready', '', ''),
('903f5d95-00ec-46dc-9e0e-f064c734b3de', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '4ba43085-30be-416a-be0f-e10844c5bfcd', '这份图片是一份合同的最后一页（第6页），页眉显示“四川欣联鑫新能源有限公司”。主要内容为合同的三项条款：
- **十三、保证担保**：丙方系乙方法定代表人，自愿为乙方履行合同义务提供连带责任保证担保，担保范围包括主债务本金、违约金及实现债权的费用等，担保期限为合同履行期限届满后三年。
- **十四、争议纠纷解决**：三方应友好协商解决争议，否则通过甲方所在地人民法院诉讼解决。
- **十五、附则**：合同自三方签字或盖章之日起生效，一式贰份，丙方身份证复印件作为附件。
页面下方为签署栏：甲方为重庆星达铜业有限公司（盖有红色合同专用章），乙方为四川欣联鑫新能源有限公司（盖有公章），双方法定代表人或代理人均已签字，丙方（签字）为叶晓霞（按有红色手印），签署日期为2025年5月13日。', '0', 't', '0', '0', '', '', 'image_caption', 'd6b7b569-c614-47bc-b740-8459b72fef84', '[{"url":"resource://8BkKUAQHKdACUQtH5Sgkcw","original_url":"resource://8BkKUAQHKdACUQtH5Sgkcw","start_pos":0,"end_pos":0,"caption":"这份图片是一份合同的最后一页（第6页），页眉显示“四川欣联鑫新能源有限公司”。主要内容为合同的三项条款：\n\n- **十三、保证担保**：丙方系乙方法定代表人，自愿为乙方履行合同义务提供连带责任保证担保，担保范围包括主债务本金、违约金及实现债权的费用等，担保期限为合同履行期限届满后三年。\n- **十四、争议纠纷解决**：三方应友好协商解决争议，否则通过甲方所在地人民法院诉讼解决。\n- **十五、附则**：合同自三方签字或盖章之日起生效，一式贰份，丙方身份证复印件作为附件。\n\n页面下方为签署栏：甲方为重庆星达铜业有限公司（盖有红色合同专用章），乙方为四川欣联鑫新能源有限公司（盖有公章），双方法定代表人或代理人均已签字，丙方（签字）为叶晓霞（按有红色手印），签署日期为2025年5月13日。","ocr_text":"十三、保证担保：\n\n丙方系乙方法定代表人，丙方自愿为乙方履行本合同项下各项义务提供连带责任保证担保，担保的范围：本合同乙方应履行的主债务本金、违约金、实现债权的费用（包括但不限于：诉讼费、律师费、保全担保费、保全费、调查取证费用等）；担保期限为：本合同履行期限届满后三年。\n\n十四、争议纠纷解决\n\n发生本合同项下之各项争议，三方友好协商解决，否则通过甲方所在地人民法院诉讼解决。\n\n十五、附则\n\n本合同自甲乙丙三方签字或盖章之日起生效。本合同一式贰份，甲乙双方执壹份，有不详之处由双方协商，与本合同具有共同的法律效力。丙方身份证复印件作为本合同附件。\n\n甲方：重庆星达铜业有限公司（盖章）\n\n乙方：四川欣联鑫新能源有限公司（盖章）\n\n法定代表人或代理人：（手写签名，字迹潦草难以辨认）\n\n法定代表人或代理人：叶晓霞（手写签名并按手印）\n\n丙方（签字）：叶晓霞（手写签名并按手印）\n\n日期：2025.5.13"}]', NULL, NULL, '2026-09-07 07:29:04.695591+00', '2026-09-07 07:29:06.280056+00', '2026-09-07 07:29:53.437631+00', NULL, '', '2', '', '1', '100000776', NULL, '这份图片是一份合同的最后一页（第6页），页眉显示“四川欣联鑫新能源有限公司”。主要内容为合同的三项条款：
- **十三、保证担保**：丙方系乙方法定代表人，自愿为乙方履行合同义务提供连带责任保证担保，担保范围包括主债务本金、违约金及实现债权的费用等，担保期限为合同履行期限届满后三年。
- **十四、争议纠纷解决**：三方应友好协商解决争议，否则通过甲方所在地人民法院诉讼解决。
- **十五、附则**：合同自三方签字或盖章之日起生效，一式贰份，丙方身份证复印件作为附件。
页面下方为签署栏：甲方为重庆星达铜业有限公司（盖有红色合同专用章），乙方为四川欣联鑫新能源有限公司（盖有公章），双方法定代表人或代理人均已签字，丙方（签字）为叶晓霞（按有红色手印），签署日期为2025年5月13日。', '0', 'ready', '', ''),
('652036a7-9469-4643-9f10-6907142533d1', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '0b633e9b-347b-4d4d-9036-317bd7f7ae65', '这是一份扫描的合同文件，为**重庆北导科技发展有限公司**的《重点运营车辆服务协议》。协议甲方为手写填写的“重庆星达铜业有限公司”，乙方为重庆北导科技发展有限公司。
主要内容包括：
- **乙方职责**：按照重庆主管部门要求为甲方车辆安装车载定位监控设备并录入管理平台；免费提供车辆监督管理平台并负责日常维护；提供监控终端维护、技术支持、设备维修与质保及平台免费升级；保障动态监控平台正常运行并对甲方安全管理人员提供技术培训。
- **甲方职责**：确保车辆信息真实有效，信息变更时及时提交乙方并在监控平台修改。
页面底部印有公司地址（重庆市渝中区石油路1号12栋1103）和联系电话（023-68724666）。', '0', 't', '0', '0', '', '', 'image_caption', '4a9fd4ed-652d-4429-95aa-f1fc31d95bc8', '[{"url":"resource://nZHOw-sT3k8VFVcmMomqEw","original_url":"resource://nZHOw-sT3k8VFVcmMomqEw","start_pos":0,"end_pos":0,"caption":"这是一份扫描的合同文件，为**重庆北导科技发展有限公司**的《重点运营车辆服务协议》。协议甲方为手写填写的“重庆星达铜业有限公司”，乙方为重庆北导科技发展有限公司。\n\n主要内容包括：\n- **乙方职责**：按照重庆主管部门要求为甲方车辆安装车载定位监控设备并录入管理平台；免费提供车辆监督管理平台并负责日常维护；提供监控终端维护、技术支持、设备维修与质保及平台免费升级；保障动态监控平台正常运行并对甲方安全管理人员提供技术培训。\n- **甲方职责**：确保车辆信息真实有效，信息变更时及时提交乙方并在监控平台修改。\n\n页面底部印有公司地址（重庆市渝中区石油路1号12栋1103）和联系电话（023-68724666）。","ocr_text":"# 重庆北导科技发展有限公司重点运营车辆服务协议\n\n**甲方：** 重庆星达铜业有限公司\n\n**乙方：** 重庆北导科技发展有限公司\n\n甲、乙双方本着诚信原则，经双方友好协商，就甲方车辆安装车载定位监控设备及后续相关服务事宜达成以下协议：\n\n## 一、乙方职责：\n\n1、乙方按照重庆区域主管部门要求，为甲方下属车辆，安装符合：交通部、重庆市运管局要求的车辆安全监控管理设备，并按照相关要求将企业、车辆信息录入对应管理平台，以便甲方车辆正常办理相关营运手续；\n\n2、乙方为甲方免费提供车辆监督管理平台的使用，并负责对平台进行日常维护；\n\n3、乙方负责提供车辆监控终端的日常维护、技术支持、设备维修与质保以及平台系统的免费升级服务；\n\n4、乙方负责车辆动态监控平台的正常运行，并配合甲方及时解决平台运营过程中出现的问题，并对甲方安全管理人员提供相关技术培训。\n\n## 二、甲方职责：\n\n1、甲方负责确保车辆信息的真实性和有效性。如车辆信息发生变更时，要第一时间把更正后的信息提交给乙方并在监控平台上进行修改；"}]', NULL, NULL, '2026-09-07 07:29:01.99743+00', '2026-09-07 07:29:03.492414+00', NULL, NULL, '', '2', '', '1', '100000767', NULL, '这是一份扫描的合同文件，为**重庆北导科技发展有限公司**的《重点运营车辆服务协议》。协议甲方为手写填写的“重庆星达铜业有限公司”，乙方为重庆北导科技发展有限公司。
主要内容包括：
- **乙方职责**：按照重庆主管部门要求为甲方车辆安装车载定位监控设备并录入管理平台；免费提供车辆监督管理平台并负责日常维护；提供监控终端维护、技术支持、设备维修与质保及平台免费升级；保障动态监控平台正常运行并对甲方安全管理人员提供技术培训。
- **甲方职责**：确保车辆信息真实有效，信息变更时及时提交乙方并在监控平台修改。
