('e6d77b8f-2426-49f7-a9dc-83f5027cdd9e', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '4ba43085-30be-416a-be0f-e10844c5bfcd', '这是一份光伏发电项目合同的第4页，出自四川欣联鑫新能源有限公司。主要内容如下：
- **施工周期**：总工期90个工作日（施工准备和安装75天，备案、申报、验收、并网15天），遇不可抗力因素经甲方确认可顺延。
- **合同总价及支付方式**：合同暂定总价281.6万元；分三笔支付（预付30%、主材验收后付30%、并网发电后付至95%），剩余5%作为质保金，质保期12个月。
- **设备要求**：采用通威TOP CON N型585-615W单晶硅组件，华为逆变器，铜芯国标电缆。
- **并网方式**：自发自用、余电上网。
- **组件标准**：单块功率不低于550瓦，使用年限25年，总衰竭不超过20%。', '0', 't', '0', '0', '', '', 'image_caption', '8cb1e29a-cd2f-493c-8672-11873a8fca4e', '[{"url":"resource://VjHuQJgCGVR1BfSvvh1cnQ","original_url":"resource://VjHuQJgCGVR1BfSvvh1cnQ","start_pos":0,"end_pos":0,"caption":"这是一份光伏发电项目合同的第4页，出自四川欣联鑫新能源有限公司。主要内容如下：\n\n- **施工周期**：总工期90个工作日（施工准备和安装75天，备案、申报、验收、并网15天），遇不可抗力因素经甲方确认可顺延。\n- **合同总价及支付方式**：合同暂定总价281.6万元；分三笔支付（预付30%、主材验收后付30%、并网发电后付至95%），剩余5%作为质保金，质保期12个月。\n- **设备要求**：采用通威TOP CON N型585-615W单晶硅组件，华为逆变器，铜芯国标电缆。\n- **并网方式**：自发自用、余电上网。\n- **组件标准**：单块功率不低于550瓦，使用年限25年，总衰竭不超过20%。","ocr_text":"五、施工周期\n\n工期从甲方支付预付款之日起计算，总工期 \u003cu\u003e90\u003c/u\u003e 个工作日，其中施工准备和安装 \u003cu\u003e75\u003c/u\u003e 个工作日，项目备案、申报、验收、并网 \u003cu\u003e15\u003c/u\u003e 个工作日。若遇天气原因或其他不可抗拒的因素，经甲方确认，工期顺延。\n\n六、合同总价及支付方式\n\n1、合同暂定总价为人民币 \u003cu\u003e281.6\u003c/u\u003e 万元（大写：\u003cu\u003e贰佰捌拾壹万陆仟元整\u003c/u\u003e）；\n\n2、支付方式：现金或银行转账结算；第一笔款项：合同签订三日内预付 30%工程款；第二笔款项：主材进场后经甲方验收确认规格型号、数量、外观质量等无异议后，三个工作内支付合同总价的 30%工程款；第三笔款项：在光伏系统并网发电三个工作日内支付至实际安装总容量金额的 95%；剩余 5%作为质保金。一兆瓦年发电量约 80 万度，上下浮动不超过百分之五；线性输出功率按厂家公式为准。发电质量保证期为 12 个月，自甲方出具书面验收报告之次日起开始计算；质保期内无重大质量问题（维修次数不超过三次或更换零件不超过 3%视为无重大质量问题），质保期届满后 10 日内向乙方支付质保金。\n\n七、本发电工程所使用的光伏组件采用通威 TOP CON N 型 585-615W 单晶硅组件，逆变器华为，所用电缆采用铜芯国标电缆。\n\n八、光伏项目的电网接入采用自发自用、余电上网方式（光伏发电优先供给企业使用，多余电量直接出售给国家电网，不足部分企业直接从国家电网购买）。\n\n九、乙方提供的光伏组件效率应符合国家认证标准，且单块组件功率不低于 550 瓦，使用年限二十五年，总衰竭不超过百分之二十。若超过百分之二十，"}]', NULL, NULL, '2026-09-07 07:29:03.001025+00', '2026-09-07 07:29:04.5036+00', '2026-09-07 07:29:53.437631+00', NULL, '', '2', '', '1', '100000771', NULL, '这是一份光伏发电项目合同的第4页，出自四川欣联鑫新能源有限公司。主要内容如下：
- **施工周期**：总工期90个工作日（施工准备和安装75天，备案、申报、验收、并网15天），遇不可抗力因素经甲方确认可顺延。
- **合同总价及支付方式**：合同暂定总价281.6万元；分三笔支付（预付30%、主材验收后付30%、并网发电后付至95%），剩余5%作为质保金，质保期12个月。
- **设备要求**：采用通威TOP CON N型585-615W单晶硅组件，华为逆变器，铜芯国标电缆。
