('8ab5e316-7bcb-473c-a72f-6eaad728bced', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '16f5c6f2-4a8e-4c23-9984-4caa0f4f8a5f', '根据《中华人民共和国民法典》等有关法律法规的规定，结合本分布式发电项目服务（以下简称项目）的具体情况，甲、乙、丙三方在遵循自愿、平等、诚实守信的基础上，签订本合同。
一、本合同重庆星达铜业有限公司屋顶光伏发电系统工程，本工程的装机容量约为 1600 千瓦，准确数据以实际安装容量为准。
二、 甲方出具授权书，授权乙方代为办理本项目涉及政府相关职能部门审批所有的申报手续，乙方免费代理上述申报事宜。甲方应提供土地证、房产证、企业营业执照、法人身份证明、委托书等。
三、本项目工程款项：彩钢瓦上平铺式含总工程款的 70%为 13%增值税发票总工程款的 30%为 9%的增值税发票，单价为（人民币）：<u>1.76</u> 元/瓦（采用通威 TOP CON N 型 585-615W 单晶硅组件），暂按 1600KW 装机计算为人民币 <u>281.6</u> 万元（大写：<u>贰佰捌拾壹万陆仟元整</u> ）计算。最终以实际装机容量结算。乙方提供的通威股份公司上述单晶硅光伏发电产品必须是生产厂家全新产品，不存在属于市场淘汰或已经拆换使用的次新产品，通威 TOP CON N 型 585-615W 单晶硅组件发电转换率为 22.6 %，否则乙方应当承担违约责任。
