('f415a52c-3bda-4370-99a4-40ff1cf55742', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '16f5c6f2-4a8e-4c23-9984-4caa0f4f8a5f', '附件2　售后服务
(1) 四川欣联鑫新能源有限公司对客户的光伏系统进行数字化管理，建立大数据平台，通过监控、通讯模块对光伏系统进行实时监测，能够掌握每个光伏系统的发电动态，对光伏系统的突发情况能够进行及时修理，对发电异常情况迅速找出原因，恢复正常发电。
(2) 我们的组件保质期为十五年，逆变器的保质期为五年。若有质量外原因导致组件损坏，公司也及时配合予以及时修换，收取成本费用。
(3) 光伏项目的审批、设计、备案、并网全部有四川欣联鑫新能源有限公司方负责。
(4) 光伏系统安装并网后二年内，每半年清洗一次，乙方就光伏组件表面清洗服务予以免费清洗。两年后，甲方要求乙方提供清洗服务的，乙方按5000元/年标准收取费用。
(5) 并网后的维护和维保由四川欣联鑫新能源有限公司负责。
(6) 因为人为破坏和自然灾害引起的，不在质保服务范畴之内，双方共同协商解决。
(7) 定期维护，日常维护与特别维护相结合（台风前后，参照防水维护并与防水维护并行检查）。', '0', 't', '0', '0', '', '', 'image_ocr', 'd3d19050-80e8-467a-931c-2c0529cba32e', '[{"url":"resource://5m72aQQ1Xd4zyAHQM0VqmQ","original_url":"resource://5m72aQQ1Xd4zyAHQM0VqmQ","start_pos":0,"end_pos":0,"caption":"这是一份四川欣联鑫新能源有限公司的文件，标题为“附件2 售后服务”。文件列出了七条光伏系统售后服务的相关条款，主要内容包括：(1) 公司对客户光伏系统进行数字化管理，建立大数据平台实时监测；(2) 组件保修期为十五年，逆变器保修期为五年；(3) 光伏项目的审批、设计、备案、并网由公司负责；(4) 并网后二年内每半年免费清洗一次光伏组件，两年后按5000元/年收费；(5) 并网后的维护维保由公司负责；(6) 人为破坏和自然灾害不在质保范围内；(7) 定期维护与日常、特别维护相结合。文件上盖有红色公司公章，页码为第8页。","ocr_text":"附件2　售后服务\n\n(1) 四川欣联鑫新能源有限公司对客户的光伏系统进行数字化管理，建立大数据平台，通过监控、通讯模块对光伏系统进行实时监测，能够掌握每个光伏系统的发电动态，对光伏系统的突发情况能够进行及时修理，对发电异常情况迅速找出原因，恢复正常发电。\n\n(2) 我们的组件保质期为十五年，逆变器的保质期为五年。若有质量外原因导致组件损坏，公司也及时配合予以及时修换，收取成本费用。\n\n(3) 光伏项目的审批、设计、备案、并网全部有四川欣联鑫新能源有限公司方负责。\n\n(4) 光伏系统安装并网后二年内，每半年清洗一次，乙方就光伏组件表面清洗服务予以免费清洗。两年后，甲方要求乙方提供清洗服务的，乙方按5000元/年标准收取费用。\n\n(5) 并网后的维护和维保由四川欣联鑫新能源有限公司负责。\n\n(6) 因为人为破坏和自然灾害引起的，不在质保服务范畴之内，双方共同协商解决。\n\n(7) 定期维护，日常维护与特别维护相结合（台风前后，参照防水维护并与防水维护并行检查）。"}]', NULL, NULL, '2026-09-07 07:29:06.249602+00', '2026-09-07 07:29:07.460887+00', NULL, NULL, '', '2', '', '1', '100000781', NULL, '附件2　售后服务
