('32a5bc0a-67e9-4daf-9016-8076576a0cb2', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '16f5c6f2-4a8e-4c23-9984-4caa0f4f8a5f', '这是一份由四川欣联鑫新能源有限公司出具的光伏发电工程合同文件（第4页），主要内容包括：
- **施工周期**：总工期90个工作日，其中施工准备和安装75个工作日，备案、申报、验收、并网15个工作日；如遇不可抗力因素，工期顺延。
- **合同总价及支付方式**：合同暂定总价为人民币281.6万元，分三期支付（预付30%、主材验收后付30%、并网发电后付至95%，余5%作为质保金），并约定了发电量及质保相关条款。
- **设备要求**：光伏组件采用通威TOPCON N型585-615W单晶硅组件，逆变器为华为品牌，电缆采用铜芯国标电缆。
- **电网接入方式**：采用自发自用、余电上网模式。
- **组件质量标准**：单块组件功率不低于550瓦，使用年限二十五年，总衰竭不超过百分之二十。', '0', 't', '0', '0', '', '', 'image_caption', 'e2b9835f-92cf-48aa-a09e-8e0a6cbaeb78', '[{"url":"resource://UxWjMomA98ctkFI5vUoDmA","original_url":"resource://UxWjMomA98ctkFI5vUoDmA","start_pos":0,"end_pos":0,"caption":"这是一份由四川欣联鑫新能源有限公司出具的光伏发电工程合同文件（第4页），主要内容包括：\n\n- **施工周期**：总工期90个工作日，其中施工准备和安装75个工作日，备案、申报、验收、并网15个工作日；如遇不可抗力因素，工期顺延。\n- **合同总价及支付方式**：合同暂定总价为人民币281.6万元，分三期支付（预付30%、主材验收后付30%、并网发电后付至95%，余5%作为质保金），并约定了发电量及质保相关条款。\n- **设备要求**：光伏组件采用通威TOPCON N型585-615W单晶硅组件，逆变器为华为品牌，电缆采用铜芯国标电缆。\n- **电网接入方式**：采用自发自用、余电上网模式。\n- **组件质量标准**：单块组件功率不低于550瓦，使用年限二十五年，总衰竭不超过百分之二十。","ocr_text":"五、施工周期\n\n工期从甲方支付预付款之日起计算，总工期 90 个工作日，其中施工准备和安装 75 个工作日，项目备案、申报、验收、并网 15 个工作日。若遇天气原因或其他不可抗拒的因素，经甲方确认，工期顺延。\n\n六、合同总价及支付方式\n\n1、合同暂定总价为人民币 281.6 万元（大写：贰佰捌拾壹万陆仟元整）；\n\n2、支付方式：现金或银行转账结算；第一笔款项：合同签订三日内预付 30%工程款；第二笔款项：主材进场后经甲方验收确认规格型号、数量、外观质量等无异议后，三个工作内支付合同总价的 30%工程款；第三笔款项：在光伏系统并网发电三个工作日内支付至实际安装总容量金额的 95%；剩余 5%作为质保金。一兆瓦年发电量约 80 万度，上下浮动不超过百分之五；线性输出功率按厂家公式为准。发电质量保证期为 12 个月，自甲方出具书面验收报告之次日起开始计算；质保期内无重大质量问题（维修次数不超过三次或更换零件不超过 3%视为无重大质量问题），质保期届满后 10 日内向乙方支付质保金。\n\n七、本发电工程所使用的光伏组件采用通威 TOP CON N 型 585-615W 单晶硅组件，逆变器华为，所用电缆采用铜芯国标电缆。\n\n八、光伏项目的电网接入采用自发自用、余电上网方式（光伏发电优先供给企业使用，多余电量直接出售给国家电网，不足部分企业直接从国家电网购买）。\n\n九、乙方提供的光伏组件效率应符合国家认证标准，且单块组件功率不低于 550 瓦，使用年限二十五年，总衰竭不超过百分之二十。若超过百分之二十，"}]', NULL, NULL, '2026-09-07 07:29:06.285673+00', '2026-09-07 07:29:08.164412+00', NULL, NULL, '', '2', '', '1', '100000784', NULL, '这是一份由四川欣联鑫新能源有限公司出具的光伏发电工程合同文件（第4页），主要内容包括：
- **施工周期**：总工期90个工作日，其中施工准备和安装75个工作日，备案、申报、验收、并网15个工作日；如遇不可抗力因素，工期顺延。
- **合同总价及支付方式**：合同暂定总价为人民币281.6万元，分三期支付（预付30%、主材验收后付30%、并网发电后付至95%，余5%作为质保金），并约定了发电量及质保相关条款。
- **设备要求**：光伏组件采用通威TOPCON N型585-615W单晶硅组件，逆变器为华为品牌，电缆采用铜芯国标电缆。
- **电网接入方式**：采用自发自用、余电上网模式。
- **组件质量标准**：单块组件功率不低于550瓦，使用年限二十五年，总衰竭不超过百分之二十。', '0', 'ready', '', ''),
