('52d32420-b9e5-4e19-a54e-cdd671f42973', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '0b633e9b-347b-4d4d-9036-317bd7f7ae65', '1、乙方计算机系统遭攻击造成严重破坏，导致乙方服务器无法正常运行期间（乙方应及时通知甲方）；
2、基础电讯运营商计划性的对短信通道进行维护期间（乙方应及时通知甲方）；
3、乙方计划性的对中心系统进行软件升级、扩容或设备维护时；
4、因网络（ISP）运营商原因而造成乙方GPS中心系统不能在互联网上正常运行。
5、用户计算机系统被病毒攻击导致无法正常使用、用户系统崩溃、计算机硬件故障等；
6、用户所属车载终端发生故障未排除期间或车载终端设备维修期间；
7、用户所属车辆行驶地未在基础电讯运营商（移动或联通）网络覆盖范围内；
