9、基础电讯运营商（移动或联通）发生不可预测性短信通道堵塞、维修等情况时。
10、用户所属车辆在规定时间内未向乙方或电讯运营商缴纳相关费用。
11、用户人为破坏车载终端、用户不配合甲方工作、车载终端严重老化、车辆长期未运行、车辆所处位置卫星信号或移动信号受到干扰等因素；
12、当发生不可抗拒的自然破坏时（地震、台风等）；
