('c5f5f551-b210-4dd9-9128-d3cc2486bfab', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '4ba43085-30be-416a-be0f-e10844c5bfcd', '这是一份四川欣联鑫新能源有限公司的文件，标题为“附件2 售后服务”，共列出7条光伏系统售后服务条款，主要内容如下：
1. 公司对客户光伏系统进行数字化管理，建立大数据平台实时监测发电动态，及时处理突发状况；
2. 光伏组件保修期十五年，逆变器保修期五年，非质量问题损坏可维修但收取成本费用；
3. 光伏项目的审批、设计、备案、并网均由该公司负责；
4. 并网后两年内每半年免费清洗一次组件，两年后按5000元/年收费；
5. 并网后的维护维保由该公司负责；
6. 人为破坏和自然灾害不在质保范围内，需双方协商解决；
7. 定期维护与日常、特别维护相结合。
文件上盖有公司红色公章，页码为8。', '0', 't', '0', '0', '', '', 'image_caption', 'd6b7b569-c614-47bc-b740-8459b72fef84', '[{"url":"resource://O91eaan8nV4E0bkHUSZenQ","original_url":"resource://O91eaan8nV4E0bkHUSZenQ","start_pos":0,"end_pos":0,"caption":"这是一份四川欣联鑫新能源有限公司的文件，标题为“附件2 售后服务”，共列出7条光伏系统售后服务条款，主要内容如下：\n\n1. 公司对客户光伏系统进行数字化管理，建立大数据平台实时监测发电动态，及时处理突发状况；\n2. 光伏组件保修期十五年，逆变器保修期五年，非质量问题损坏可维修但收取成本费用；\n3. 光伏项目的审批、设计、备案、并网均由该公司负责；\n4. 并网后两年内每半年免费清洗一次组件，两年后按5000元/年收费；\n5. 并网后的维护维保由该公司负责；\n6. 人为破坏和自然灾害不在质保范围内，需双方协商解决；\n7. 定期维护与日常、特别维护相结合。\n\n文件上盖有公司红色公章，页码为8。","ocr_text":"附件2　售后服务\n\n(1) 四川欣联鑫新能源有限公司对客户的光伏系统进行数字化管理，建立大数据平台，通过监控、通讯模块对光伏系统进行实时监测，能够掌握每个光伏系统的发电动态，对光伏系统的突发情况能够进行及时修理，对发电异常情况迅速找出原因，恢复正常发电。\n\n(2) 我们的组件保质期为十五年，逆变器的保质期为五年。若有质量外原因导致组件损坏，公司也及时配合予以及时修换，收取成本费用。\n\n**(3)** 光伏项目的审批、设计、备案、并网全部有四川欣联鑫新能源有限公司方负责。\n\n(4) 光伏系统安装并网后二年内，每半年清洗一次，乙方就光伏组件表面清洗服务予以免费清洗。两年后，甲方要求乙方提供清洗服务的，乙方按 **5000** 元/年标准收取费用。\n\n(5) 并网后的维护和维保由四川欣联鑫新能源有限公司负责。\n\n(6) 因为人为破坏和自然灾害引起的，不在质保服务范畴之内，双方共同协商解决。\n\n(7) 定期维护，日常维护与特别维护相结合（台风前后，参照防水维护并与防水维护并行检查）。"}]', NULL, NULL, '2026-09-07 07:29:05.073943+00', '2026-09-07 07:29:06.76268+00', '2026-09-07 07:29:53.437631+00', NULL, '', '2', '', '1', '100000780', NULL, '这是一份四川欣联鑫新能源有限公司的文件，标题为“附件2 售后服务”，共列出7条光伏系统售后服务条款，主要内容如下：
1. 公司对客户光伏系统进行数字化管理，建立大数据平台实时监测发电动态，及时处理突发状况；
2. 光伏组件保修期十五年，逆变器保修期五年，非质量问题损坏可维修但收取成本费用；
3. 光伏项目的审批、设计、备案、并网均由该公司负责；
4. 并网后两年内每半年免费清洗一次组件，两年后按5000元/年收费；
5. 并网后的维护维保由该公司负责；
6. 人为破坏和自然灾害不在质保范围内，需双方协商解决；
7. 定期维护与日常、特别维护相结合。
文件上盖有公司红色公章，页码为8。', '0', 'ready', '', ''),
