本文件为国网重庆市电力公司出具的电费账单，账单对象为市场化零售客户重庆星达铜业有限公司（户号5001654065328），用电类别为大工业用电，电压等级为交流10kV，供电服务单位为璧城供电服务中心，用电地址位于重庆市璧山区青杠街道。账单周期为2026年7月1日至7月31日，打印日期为2026年8月5日，交费截止日期为2026年8月9日。本期总电量为655058千瓦时，总电费为471420.85元。
账单费用主要由工商业电费、居民电费和功率因数调整电费构成。工商业电费计费电量645237千瓦时，金额469266.76元，包含五部分：市场化购电费266658.01元（其中零售交易电费281323.34元，另有零售损益分摊、中长期偏差回收返还、超额申报费用返还及发电侧收益返还等调整项）；上网环节线损费用11816.23元；输配电费123416.88元（含电量电费79416.88元及按2000千伏安容量、22元单价计收的容量电费44000元）；系统运行费36601.71元（含煤电容量电费14565.58元、燃气机组容量电费9532.09元、新能源机制差价分摊、抽水蓄能容量电费等）；政府性基金及附加30773.93元（含农网还贷、可再生能源附加、库区移民基金等）。居民电费按定比0.015计提，电量9821千瓦时，金额5205.13元。因实际功率因数0.97高于0.90的标准，功率因数调整电费为-3051.04元。
用能分析方面：本期电量环比增长1.42%；尖峰平谷分时电量比例为1.71%、16.61%、32.09%、49.59%，低谷用电占比有所上升；实际功率因数0.97与上期持平；平均电价0.71966元/千瓦时，较上期微增0.00023元。
账单详情部分显示，计费电能表编号为5030001221300052554525，倍率3000，执行“大工业用电-工商业两部制-分时”电价，正向有功总抄见电量654720千瓦时，零售交易电费统一按0.436元/千瓦时计收，输配电量电费按分时差异计价。账单备注还说明了两部制用户可在容量与需量计费方式间选择（需提前15个工作日申请且三个月内不变），以及工商业用户尖峰12:00-14:00、高峰11:00-12:00等分时段划分规则。', '9', 't', '0', '0', '', '', 'summary', '7a33dbc1-c047-4f59-a05a-d9055ca0e287', '', NULL, NULL, '2026-09-09 04:45:19.656254+00', '2026-09-09 04:45:19.656254+00', '2026-09-10 03:44:03.828075+00', NULL, '', '0', '', '1', '100000918', NULL, '# Summary
本文件为国网重庆市电力公司出具的电费账单，账单对象为市场化零售客户重庆星达铜业有限公司（户号5001654065328），用电类别为大工业用电，电压等级为交流10kV，供电服务单位为璧城供电服务中心，用电地址位于重庆市璧山区青杠街道。账单周期为2026年7月1日至7月31日，打印日期为2026年8月5日，交费截止日期为2026年8月9日。本期总电量为655058千瓦时，总电费为471420.85元。
账单费用主要由工商业电费、居民电费和功率因数调整电费构成。工商业电费计费电量645237千瓦时，金额469266.76元，包含五部分：市场化购电费266658.01元（其中零售交易电费281323.34元，另有零售损益分摊、中长期偏差回收返还、超额申报费用返还及发电侧收益返还等调整项）；上网环节线损费用11816.23元；输配电费123416.88元（含电量电费79416.88元及按2000千伏安容量、22元单价计收的容量电费44000元）；系统运行费36601.71元（含煤电容量电费14565.58元、燃气机组容量电费9532.09元、新能源机制差价分摊、抽水蓄能容量电费等）；政府性基金及附加30773.93元（含农网还贷、可再生能源附加、库区移民基金等）。居民电费按定比0.015计提，电量9821千瓦时，金额5205.13元。因实际功率因数0.97高于0.90的标准，功率因数调整电费为-3051.04元。
用能分析方面：本期电量环比增长1.42%；尖峰平谷分时电量比例为1.71%、16.61%、32.09%、49.59%，低谷用电占比有所上升；实际功率因数0.97与上期持平；平均电价0.71966元/千瓦时，较上期微增0.00023元。
账单详情部分显示，计费电能表编号为5030001221300052554525，倍率3000，执行“大工业用电-工商业两部制-分时”电价，正向有功总抄见电量654720千瓦时，零售交易电费统一按0.436元/千瓦时计收，输配电量电费按分时差异计价。账单备注还说明了两部制用户可在容量与需量计费方式间选择（需提前15个工作日申请且三个月内不变），以及工商业用户尖峰12:00-14:00、高峰11:00-12:00等分时段划分规则。', '0', 'ready', '', ''),
