文件上盖有红色合同专用印章。', '0', 't', '0', '0', '', '', 'image_caption', '950957a0-7495-4741-bdd2-59244dd66ab9', '[{"url":"resource://GtNVX9o5czjI_W6O3NQnMQ","original_url":"resource://GtNVX9o5czjI_W6O3NQnMQ","start_pos":0,"end_pos":0,"caption":"这是一份《体系咨询顾问服务协议》合同文件。主要内容如下：\n\n- **合同编号**：QC-XMIT20251003\n- **甲方**：重庆星达铜业有限公司（联系人薛晋川）\n- **乙方**：云南谋虑企业管理咨询有限公司（联系人李受萍），并附有兴业银行收款账户信息\n- **服务内容**：IATF16949质量管理体系认证，分两阶段支付各17500元，合计35000元\n- **服务期限**：2025年10月30日至2028年10月29日，共3年，包含体系辅导、申谱、审核出证等\n- **付款方式**：合同签订后支付第一阶段费用，电子证书下发后支付第二阶段费用，仅限公司账户资金支付\n- **其他条款**：包括甲方权利与义务、退款项约定等\n\n文件上盖有红色合同专用印章。","ocr_text":"# 体系咨询顾问服务协议\n\n合同编号：QC-XMIT20251003\n\n甲方：重庆星达铜业有限公司\n\n联系人：薛晋川\u0026emsp;\u0026emsp;\u0026emsp;\u0026emsp;联系电话：13880039136\n\n联系地址：重庆市璧山区青杠街道新立路106号\n\n乙方：云南谏虑企业管理咨询有限公司\n\n联系人：李受萍\u0026emsp;\u0026emsp;\u0026emsp;\u0026emsp;联系电话：18314508364\n\n联系地址：云南省昆明市高新区昆百大国际派A座35楼3502\n\n账户信息：\n\n开户行：兴业银行股份有限公司昆明北京路支行\n\n收款账户：云南谏虑企业管理咨询有限公司\u0026emsp;\u0026emsp;\u0026emsp;\u0026emsp;收款账号：471100100100217565\n\n甲乙双方友好协商，就乙方为甲方提供体系 认证服务，根据《中华人民共和国民法典》等相关法律法规的规定，本着诚信友好、互惠互利的原则，双方达成如下协议，以资共同遵守。\n\n## 一、服务事项\n\n1. 服务产品填写（必填）\n\n| 产品名称 | 第一阶段支付金额（单位：元） | 第二阶段支付金额（单位：元） |\n| --- | --- | --- |\n| IATF16949质量管理体系认证 | 17500 | 17500 |\n| 阶段合计金额 | 17500 | 17500 |\n| 合计金额 | 35000 | |\n\n2. 合同服务期限：2025 年 10 月 30 日至 2028 年 10 月 29 日（合同服务期为 3 年），服务周期包含体系辅导、体系申谱、体系审核出证等，合同服务期限结束后，如乙方在服务过程中已提供服务但申请事项/请求事项被全部驳回或者未通过认定（认证）的，乙方将为甲方再次提交材料，直至体系认证成功为止，甲方可向乙方申请退款，从甲方提出退款申请之日起，乙方需提供所开具的发票做冲红手续，并原路退回所收款项。\n\n## 二、服务费用及支付方式\n\n1. 合同签订后甲方向乙方支付第一阶段体系服务费用合计人民币￥ 17500 元整（大写：壹万柒仟伍佰圆整），电子证书下发后支付第二阶段体系服务费用合计人民币￥ 17500 元整（大写：壹万柒仟伍佰圆整），乙方应在收款前出具相应发票。\n\n2. 付款方式：甲方通过 现金□ 银行转账□ POS刷卡□ 对公转账□ 的方式向乙方支付约定款项。\n\n3. 支付方式仅限公司账户资金支付。\n\n4. 该笔费用为此次认证费用的包干价（包括但不限于申请费、文审费、证书费、年费、标志使用费、注册费、辅导费、文件编制费、审核人员住宿、交通、专家费等）。\n\n## 三、甲方权利与义务\n\n1. 甲方指派固定联系人与乙方进行沟通、联系，配合乙方的工作，甲方如变更联系人或联系方式须主动以书面形式（包括经乙方确认的电子邮件）通知乙方。否则，由此造成乙方无法与甲方及时联系所产生的后果，由甲方自行负责。\n\n2. 甲方须及时提供上述体系认证工作所需的全部资料，并协助乙方体系小组完成上述体系认证工作；上述全部资料包括但不限于企业基本信息、财务报表和相关证明材料原件等体系认证所需资料。"}]', NULL, NULL, '