('c90cb1a5-814c-4e5e-b20d-6633d2d2d374', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '0b633e9b-347b-4d4d-9036-317bd7f7ae65', '# Summary
这份文件是重庆北导科技发展有限公司与重庆星达铜业有限公司签订的《重点运营车辆服务协议》。协议中明确了双方的职责和权利。
乙方（重庆北导科技发展有限公司）的主要职责包括：为甲方（重庆星达铜业有限公司）的车辆安装车载定位监控设备并录入管理平台；提供车辆监督管理平台并负责日常维护；提供监控终端维护、技术支持、设备维修与质保及平台免费升级；保障动态监控平台正常运行并对甲方安全管理人员提供技术培训。
甲方的主要职责是确保车辆信息的真实性和有效性，并在信息变更时及时提交给乙方并在监控平台上进行修改。
此外，协议还规定了设备付费方式、移机服务收费标准、乙方银行账户信息、设备质保条款以及管理系统维护责任等内容。设备采用购买方式，首次费用在设备安装验收完毕后10个工作日内支付。合同期内，如因车辆报废或其他原因造成不能在原安装车辆继续使用的情况，乙方提供有偿移机服务，收费标准为100元/台/次。乙方为设备提供服务期内免费质保，质保期外及人为损坏，乙方提供收费服务。乙方负责GPS车辆定位监控系统的技术维护，网络故障及其他疑难故障查询，但甲方应积极配合。', '1', 't', '0', '0', '', '', 'summary', '4a9fd4ed-652d-4429-95aa-f1fc31d95bc8', '', NULL, NULL, '2026-09-07 07:29:17.351276+00', '2026-09-07 07:29:17.351276+00', NULL, NULL, '', '0', '', '1', '100000797', NULL, '# Summary
这份文件是重庆北导科技发展有限公司与重庆星达铜业有限公司签订的《重点运营车辆服务协议》。协议中明确了双方的职责和权利。
乙方（重庆北导科技发展有限公司）的主要职责包括：为甲方（重庆星达铜业有限公司）的车辆安装车载定位监控设备并录入管理平台；提供车辆监督管理平台并负责日常维护；提供监控终端维护、技术支持、设备维修与质保及平台免费升级；保障动态监控平台正常运行并对甲方安全管理人员提供技术培训。
甲方的主要职责是确保车辆信息的真实性和有效性，并在信息变更时及时提交给乙方并在监控平台上进行修改。
此外，协议还规定了设备付费方式、移机服务收费标准、乙方银行账户信息、设备质保条款以及管理系统维护责任等内容。设备采用购买方式，首次费用在设备安装验收完毕后10个工作日内支付。合同期内，如因车辆报废或其他原因造成不能在原安装车辆继续使用的情况，乙方提供有偿移机服务，收费标准为100元/台/次。乙方为设备提供服务期内免费质保，质保期外及人为损坏，乙方提供收费服务。乙方负责GPS车辆定位监控系统的技术维护，网络故障及其他疑难故障查询，但甲方应积极配合。', '0', 'ready', '', ''),
('d3e4d1a5-f22e-4025-9d65-6b96fad1007a', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', 'c2dfb7c0-debc-4358-b836-31817ebee717', '3. 甲方应向乙方提供真实、准确的资料，如因提供虚假资料而产生纠纷或损失（如认证不成功），由甲方自行承担相应责任。
4. 甲方应根据乙方的建议，积极创造条件，采取必要行动，落实乙方的方案和建议，达到上述各体系认证的要求。
四、乙方权利与义务
1. 乙方针对甲方的认证体系，成立两人以上的体系认证小组负责甲方体系认证，并提出针对性策划、培育计划、整改目标及实施方案，并指导且协助甲方进行落实。
2. 乙方应根据体系认证要求，协助甲方撰写、收集、整理体系认证材料，并在指定时限内递交认证材料。
3. 乙方应协助甲方准备体系认证的现场检查或验收工作，并将体系认证办理进程告知甲方。
4. 乙方应在体系认证条件发生变化时，及时通知甲方并调整实施方案。
五、违约责任
1. 甲方应按本合同约定及时向乙方支付体系认证服务费用，逾期未支付给乙方，此协议即自动解除。
2. 合同签订生效后，非因乙方过错，甲方无故中途取消/终止相应体系认证工作、并在甲方能力范围内（营业执照、开户许可证、法人身份证、土地租赁协议、商业计划书、可行性研究报告、财务报表等资料）不予配合乙方有关体系认证工作的，相应风险及服务费用由甲方承担。
3. 乙方向甲方提供的相应体系认证信息或方案，发生以下情形的，视同乙方已成功办理该合同体系，甲方应按本合同第二条约定的费用及支付方式向乙方支付服务费用。
1）. 未经乙方书面同意，甲方另行委托其他第三方代为认证或自行认证的；
2）. 未经乙方书面同意，甲方另以其关联公司、子公司或第三方公司的名义认证合同体系的。
4. 乙方因泄露或以其他方式侵犯甲方的商业秘密，给甲方造成损失的，乙方应赔偿甲方的经济损失。
六、保密条款
甲乙双方对本合同内容及合同履行过程中知悉的双方所有的经营信息、资料等商业秘密负有保密义务，未经对方许可不得自行用于与本合同目的无关的其它事务或向任何第三方泄露、出售、许可使用，但法律要求披露或者通过合法公开途径可获得的除外。
七、争议解决
本合同履行过程中产生的一切争议，均应由双方友好协商解决；如协商不成，任何一方均有权向甲方所在地人民法院提起诉讼。
八、合同生效及其他
1. 本合同文本规定之条款如有未尽或变更事宜，由双方协商补充，补充协议与本合同具有同等法律效力。
2. 本合同履行和相关事宜的通知，应当按照本合同载明的地址发出。如果以特快专递或挂号信形式寄出，自发出之日起的第四日视为送达。
3. 本合同一式两份，自双方签章之日起生效。甲乙双方各执一份，具有同等法律效力。
甲方（签章）：
代表人：
日期：　　　年　　月　　日
乙方（签章）：
代表人：
