('55ef1159-9809-46cb-8ad3-6a38dec858ce', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '0b633e9b-347b-4d4d-9036-317bd7f7ae65', '# 八、违约责任：
1、双方对本协议相关条款予以充分说明，对协议内容的理解不存在异议，并承诺严格履行协议义务，签订本协议后，未经双方书面同意，一方不得无故单方面终止协议，否则视为违约。
2、任何一方违反本协议约定的行为均视为违约，违约方须向守约方支付本合同约定的一年业务服务费作为违约金，并赔偿守约方遭受的损失，违约严重时，守约方可单方解除本协议。
3、一方应自觉维护另一方的商业形象和声誉，关注另一方利益，自觉保守本协议内容及对方的技术、商业秘密，以及对方明确提示需要保密的内容，如一方违约（比如泄露技术、商业机密等）造成另一方损失，违约方应负责赔偿受损方相应违约金。
4、如果因不可抗力、政府、政策、市场竞争环境发生重大变化等原因导致双方协议不能履行或不能完全履行的，甲、乙方互不承担责任，如果有损失产生，由双方友好协商解决，对于协议终止前已经接入甲方平台的车辆，乙方不得转出。
# 九、协议有效期限：
本协议有效期为 <u>5</u> 年，从 <u>2025</u> 年 <u>1</u> 月 <u>8</u> 日至 <u>2028</u> 年 <u>1</u> 月 <u>7</u> 日止，双方签字盖章后生效，甲、乙方在协议期限届满前一个月如无异议，则本协议视为自动延期。
# 十、其它：
1、本协议生效后，双方应当诚信、全面履约，一方严重违约，另一方有权终止协议，未尽事宜，由甲、乙方共同协商解决，签订书面补充协议；', '0', 't', '0', '0', '', '', 'image_ocr', '4a9fd4ed-652d-4429-95aa-f1fc31d95bc8', '[{"url":"resource://edV1hHVpzH2D8p-OD_fQVA","original_url":"resource://edV1hHVpzH2D8p-OD_fQVA","start_pos":0,"end_pos":0,"caption":"这是一份重庆北导科技发展有限公司的协议合同页面，主要内容包括：\n\n- **第八条 违约责任**：共四款，规定双方须严格履行协议，未经书面同意不得单方终止；违约方须支付一年业务服务费作为违约金并赔偿损失；双方应保守对方技术、商业秘密，泄密需赔偿；因不可抗力或政策、市场重大变化导致协议无法履行的，双方互不承担责任。\n\n- **第九条 协议有效期限**：手写注明协议有效期为5年，自2025年1月8日至2028年1月7日止，期满前一个月如无异议则自动延期。\n\n- **第十条 其它**：规定协议生效后双方应诚信履约，未尽事宜协商解决并签订补充协议。\n\n页面右侧盖有红色公司公章，页脚印有公司地址（重庆市渝中区石油路1号12栋1103）和联系电话。","ocr_text":"# 八、违约责任：\n\n1、双方对本协议相关条款予以充分说明，对协议内容的理解不存在异议，并承诺严格履行协议义务，签订本协议后，未经双方书面同意，一方不得无故单方面终止协议，否则视为违约。\n\n2、任何一方违反本协议约定的行为均视为违约，违约方须向守约方支付本合同约定的一年业务服务费作为违约金，并赔偿守约方遭受的损失，违约严重时，守约方可单方解除本协议。\n\n3、一方应自觉维护另一方的商业形象和声誉，关注另一方利益，自觉保守本协议内容及对方的技术、商业秘密，以及对方明确提示需要保密的内容，如一方违约（比如泄露技术、商业机密等）造成另一方损失，违约方应负责赔偿受损方相应违约金。\n\n4、如果因不可抗力、政府、政策、市场竞争环境发生重大变化等原因导致双方协议不能履行或不能完全履行的，甲、乙方互不承担责任，如果有损失产生，由双方友好协商解决，对于协议终止前已经接入甲方平台的车辆，乙方不得转出。\n\n# 九、协议有效期限：\n\n本协议有效期为 \u003cu\u003e5\u003c/u\u003e 年，从 \u003cu\u003e2025\u003c/u\u003e 年 \u003cu\u003e1\u003c/u\u003e 月 \u003cu\u003e8\u003c/u\u003e 日至 \u003cu\u003e2028\u003c/u\u003e 年 \u003cu\u003e1\u003c/u\u003e 月 \u003cu\u003e7\u003c/u\u003e 日止，双方签字盖章后生效，甲、乙方在协议期限届满前一个月如无异议，则本协议视为自动延期。\n\n# 十、其它：\n\n1、本协议生效后，双方应当诚信、全面履约，一方严重违约，另一方有权终止协议，未尽事宜，由甲、乙方共同协商解决，签订书面补充协议；"}]', NULL, NULL, '2026-09-07 07:29:36.612933+00', '2026-09-07 07:29:37.642238+00', NULL, NULL, '', '2', '', '1', '100000803', NULL, '# 八、违约责任：
