('243fbe4d-826b-4e18-9825-2fbf2e1047f9', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '4ba43085-30be-416a-be0f-e10844c5bfcd', '这是一份《重庆星达铜业有限公司光伏发电项目安装总合同》的首页。合同甲方（需方）为重庆星达铜业有限公司，住所地位于重庆市璧山区青杠街道新立路106号，法定代表人为彭嘉奕；乙方（供方）为四川欣联鑫新能源有限公司，法定代表人叶晓霞；丙方（担保人）为叶晓霞，并附有身份证号。页面上盖有双方的红色公章及手印，表明合同已经签署盖章。', '0', 't', '0', '0', '', '', 'image_caption', '8cb1e29a-cd2f-493c-8672-11873a8fca4e', '[{"url":"resource://mOSgY8lUM0B33aTYuo2cEw","original_url":"resource://mOSgY8lUM0B33aTYuo2cEw","start_pos":0,"end_pos":0,"caption":"这是一份《重庆星达铜业有限公司光伏发电项目安装总合同》的首页。合同甲方（需方）为重庆星达铜业有限公司，住所地位于重庆市璧山区青杠街道新立路106号，法定代表人为彭嘉奕；乙方（供方）为四川欣联鑫新能源有限公司，法定代表人叶晓霞；丙方（担保人）为叶晓霞，并附有身份证号。页面上盖有双方的红色公章及手印，表明合同已经签署盖章。","ocr_text":"四川欣联鑫新能源有限公司\n\n# 重庆星达铜业有限公司\n# 光伏发电项目安装总合同\n\n甲方（需方）：重庆星达铜业有限公司\n\n住所地：重庆市璧山区青杠街道新立路106号\n\n法定代表人：彭嘉奕\n\n乙方（供方）：四川欣联鑫新能源有限公司\n\n住所地：\n\n法定代表人：叶晓霞\n\n丙方（担保人）：叶晓霞　身份证号：33032419741203342X\n\n地址："}]', NULL, NULL, '2026-09-07 07:28:58.465668+00', '2026-09-07 07:29:00.03727+00', '2026-09-07 07:29:53.437631+00', NULL, '', '2', '', '1', '100000761', NULL, '这是一份《重庆星达铜业有限公司光伏发电项目安装总合同》的首页。合同甲方（需方）为重庆星达铜业有限公司，住所地位于重庆市璧山区青杠街道新立路106号，法定代表人为彭嘉奕；乙方（供方）为四川欣联鑫新能源有限公司，法定代表人叶晓霞；丙方（担保人）为叶晓霞，并附有身份证号。页面上盖有双方的红色公章及手印，表明合同已经签署盖章。', '0', 'ready', '', ''),
('ff3ddef3-6261-461a-a9b7-3b4f90d8e1d0', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '4ba43085-30be-416a-be0f-e10844c5bfcd', '这是一份合同文件的第五页，页眉显示为“四川欣联鑫新能源有限公司”，页面上盖有红色印章。主要内容包括：
- **第十条**：乙方提供的产品须符合国家或行业标准，并附说明书、质量合格证、质保书等资料。
- **第十一条**：质量保修条款——整系统保修五年，逆变器质保五年，组件质保十五年；保修期内非人为损坏，乙方须三日内派员免费维修，否则承担发电损失或第三方维修费用。
- **第十二条**：违约责任——产品不合格须三日内更换，逾期按合同总价1‰/日支付违约金；逾期交货或安装同样按1‰/日计罚；因不可抗力等可顺延工期；若乙方拒不配合整改，甲方可解除合同，乙方须退还全部款项并承担合同总价30%的违约金。', '0', 't', '0', '0', '', '', 'image_caption', '8cb1e29a-cd2f-493c-8672-11873a8fca4e', '[{"url":"resource://vZQisEqSfwcxTbho6WFnFw","original_url":"resource://vZQisEqSfwcxTbho6WFnFw","start_pos":0,"end_pos":0,"caption":"这是一份合同文件的第五页，页眉显示为“四川欣联鑫新能源有限公司”，页面上盖有红色印章。主要内容包括：\n\n- **第十条**：乙方提供的产品须符合国家或行业标准，并附说明书、质量合格证、质保书等资料。\n- **第十一条**：质量保修条款——整系统保修五年，逆变器质保五年，组件质保十五年；保修期内非人为损坏，乙方须三日内派员免费维修，否则承担发电损失或第三方维修费用。\n- **第十二条**：违约责任——产品不合格须三日内更换，逾期按合同总价1‰/日支付违约金；逾期交货或安装同样按1‰/日计罚；因不可抗力等可顺延工期；若乙方拒不配合整改，甲方可解除合同，乙方须退还全部款项并承担合同总价30%的违约金。","ocr_text":"其衰竭超出部分乙方按实时电价补差至甲方，甲方有权先行向乙方就上述补偿方式计算的损失进行索赔。\n\n十、乙方向甲方提供的全部产品均应满足国家或行业标准的要求，系统产品应有说明书、质量合格证、组件产品质保书及其他有关资料。详见附件 1\n\n十一、自通过验收合格之日起，整个系统质量保修期为五年。逆变器保质期五年，组件质保期为十五年。保修期内在非人为损坏的情况下如发现系统故障，乙必须在接到通知其知三日内派员解决，并在三日内解决问题，并免收一切服务费用。详见附件 2，如果乙方未能及时指派维修人员解决质量问题，所造成的发电损失应当由乙方承担；或甲方有权委托第三方进行维修，所产生的维修费（包括但不限于人工费用、零件更换等费用）应当由乙方承担。\n\n十二、违约责任\n\n1、乙方提供的产品不符合合同要求，乙方应当在三日内更换全新产品；否则乙方应当承担逾期更换的违约责任，违约金为合同总价 1‰/日；\n\n2、乙方逾期交货或逾期安装完工，乙方应当自逾期之日起按照合同总价 1‰/日承担违约金，如遇不可抗力（如地震、战争、极端天气、政府管控等）、发改委及供电部门手续延迟、疫情防控要求停工，甲方盖章用印流程滞后等因素导致影响工期延误的，则工期相应顺延；乙方交付的光伏电站因质量原因由相关部门验收不通过的，乙方应当无条件整改至验收通过；若乙方拒不配合甲方有权单方面无条件解除本合同，乙方应当退还甲方已支付的全部款项，并承担合同总价 30%的违约金。"}]', NULL, NULL, '2026-09-07 07:29:03.990305+00', '2026-09-07 07:29:05.461061+00', '2026-09-07 07:29:53.437631+00', NULL, '', '2', '', '1', '100000773', NULL, '这是一份合同文件的第五页，页眉显示为“四川欣联鑫新能源有限公司”，页面上盖有红色印章。主要内容包括：
- **第十条**：乙方提供的产品须符合国家或行业标准，并附说明书、质量合格证、质保书等资料。
- **第十一条**：质量保修条款——整系统保修五年，逆变器质保五年，组件质保十五年；保修期内非人为损坏，乙方须三日内派员免费维修，否则承担发电损失或第三方维修费用。
- **第十二条**：违约责任——产品不合格须三日内更换，逾期按合同总价1‰/日支付违约金；逾期交货或安装同样按1‰/日计罚；因不可抗力等可顺延工期；若乙方拒不配合整改，甲方可解除合同，乙方须退还全部款项并承担合同总价30%的违约金。', '0', 'ready', '', ''),
('5c2551b8-26e8-4cb4-895e-23214c3fad85', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '4ba43085-30be-416a-be0f-e10844c5bfcd', '附件2　售后服务
(1) 四川欣联鑫新能源有限公司对客户的光伏系统进行数字化管理，建立大数据平台，通过监控、通讯模块对光伏系统进行实时监测，能够掌握每个光伏系统的发电动态，对光伏系统的突发情况能够进行及时修理，对发电异常情况迅速找出原因，恢复正常发电。
(2) 我们的组件保质期为十五年，逆变器的保质期为五年。若有质量外原因导致组件损坏，公司也及时配合予以及时修换，收取成本费用。
**(3)** 光伏项目的审批、设计、备案、并网全部有四川欣联鑫新能源有限公司方负责。
(4) 光伏系统安装并网后二年内，每半年清洗一次，乙方就光伏组件表面清洗服务予以免费清洗。两年后，甲方要求乙方提供清洗服务的，乙方按 **5000** 元/年标准收取费用。
(5) 并网后的维护和维保由四川欣联鑫新能源有限公司负责。
(6) 因为人为破坏和自然灾害引起的，不在质保服务范畴之内，双方共同协商解决。
(7) 定期维护，日常维护与特别维护相结合（台风前后，参照防水维护并与防水维护并行检查）。', '0', 't', '0', '0', '', '', 'image_ocr', 'd6b7b569-c614-47bc-b740-8459b72fef84', '[{"url":"resource://O91eaan8nV4E0bkHUSZenQ","original_url":"resource://O91eaan8nV4E0bkHUSZenQ","start_pos":0,"end_pos":0,"caption":"这是一份四川欣联鑫新能源有限公司的文件，标题为“附件2 售后服务”，共列出7条光伏系统售后服务条款，主要内容如下：\n\n1. 公司对客户光伏系统进行数字化管理，建立大数据平台实时监测发电动态，及时处理突发状况；\n2. 光伏组件保修期十五年，逆变器保修期五年，非质量问题损坏可维修但收取成本费用；\n3. 光伏项目的审批、设计、备案、并网均由该公司负责；\n4. 并网后两年内每半年免费清洗一次组件，两年后按5000元/年收费；\n5. 并网后的维护维保由该公司负责；\n6. 人为破坏和自然灾害不在质保范围内，需双方协商解决；\n7. 定期维护与日常、特别维护相结合。\n\n文件上盖有公司红色公章，页码为8。","ocr_text":"附件2　售后服务\n\n(1) 四川欣联鑫新能源有限公司对客户的光伏系统进行数字化管理，建立大数据平台，通过监控、通讯模块对光伏系统进行实时监测，能够掌握每个光伏系统的发电动态，对光伏系统的突发情况能够进行及时修理，对发电异常情况迅速找出原因，恢复正常发电。\n\n(2) 我们的组件保质期为十五年，逆变器的保质期为五年。若有质量外原因导致组件损坏，公司也及时配合予以及时修换，收取成本费用。\n\n**(3)** 光伏项目的审批、设计、备案、并网全部有四川欣联鑫新能源有限公司方负责。\n\n(4) 光伏系统安装并网后二年内，每半年清洗一次，乙方就光伏组件表面清洗服务予以免费清洗。两年后，甲方要求乙方提供清洗服务的，乙方按 **5000** 元/年标准收取费用。\n\n(5) 并网后的维护和维保由四川欣联鑫新能源有限公司负责。\n\n(6) 因为人为破坏和自然灾害引起的，不在质保服务范畴之内，双方共同协商解决。\n\n(7) 定期维护，日常维护与特别维护相结合（台风前后，参照防水维护并与防水维护并行检查）。"}]', NULL, NULL, '2026-09-07 07:29:05.073943+00', '2026-09-07 07:29:06.484736+00', '2026-09-07 07:29:53.437631+00', NULL, '', '2', '', '1', '100000779', NULL, '附件2　售后服务
