('0f8e13e1-2f00-40e6-9251-c570a74acd72', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '4ba43085-30be-416a-be0f-e10844c5bfcd', '这是一份由四川欣联鑫新能源有限公司出具的文件，标题为“附件1：主要材料清单”。文件主体是一张表格，列出了光伏发电项目所需的主要材料及其标准、品牌和材质，包括：通威550W及以上单晶组件、华为逆变器和GRPS模块、国标铜芯直流/交流电缆、热镀锌C型钢及支架、铝合金压扣夹具、304不锈钢螺丝、浙江欧惠MC4端子、昌松电力防孤岛及防雷装置、接地扁铁以及其他辅助材料等。文件上盖有红色公章，页码为第7页。', '0', 't', '0', '0', '', '', 'image_caption', 'd6b7b569-c614-47bc-b740-8459b72fef84', '[{"url":"resource://lRjxQGiA7rC6idDwFIu3Tw","original_url":"resource://lRjxQGiA7rC6idDwFIu3Tw","start_pos":0,"end_pos":0,"caption":"这是一份由四川欣联鑫新能源有限公司出具的文件，标题为“附件1：主要材料清单”。文件主体是一张表格，列出了光伏发电项目所需的主要材料及其标准、品牌和材质，包括：通威550W及以上单晶组件、华为逆变器和GRPS模块、国标铜芯直流/交流电缆、热镀锌C型钢及支架、铝合金压扣夹具、304不锈钢螺丝、浙江欧惠MC4端子、昌松电力防孤岛及防雷装置、接地扁铁以及其他辅助材料等。文件上盖有红色公章，页码为第7页。","ocr_text":"# 附件 1：主要材料清单\n\n## 主要材料清单\n\n| 材料 | 标准 | 品牌 | 材质 | 备注 |\n| --- | --- | --- | --- | --- |\n| 组件 |  | 通威 550W 及以上 | 单晶 |  |\n| 逆变器 |  | “华为” |  |  |\n| GRPS 模块 |  | “华为” |  |  |\n| 光伏直流电缆 | 国标 | 直流 PVlx4 截面面积 4 平方毫米 | 铜 |  |\n| 交流电缆 | 国标 | 中策 | 铜 |  |\n| 线缆桥架 | 国标 | 浙江协胜 |  |  |\n| C 型钢 |  | 41x41C 型钢(天津）平铺式 | 热镀锌 |  |\n| 压扣及底座夹具 |  |  | 铝合金 |  |\n| 螺丝 |  |  | 304 不锈钢 |  |\n| MC4 端子 | 国标 | 浙江欧惠 |  |  |\n| 并网箱 | 国标 |  |  | 由电网公司指定 |\n| 防孤岛装置 | 国网 | 昌松电力 |  |  |\n| 防避雷装置 | 国标 | 昌松电力 |  |  |\n| 接地扁铁 | 国标 | 40*4 扁铁 | 热镀锌 |  |\n| 其他辅材 | 国标 | 膨胀螺栓、线管、防火泥、油漆、焊条、铜鼻子等等 |  |  |\n| 支架 |  | 热镀锌 | 热镀锌 |  |\n| 施工现场管理 |  | 工程项目经理 |  |  |"}]', NULL, NULL, '2026-09-07 07:29:11.200991+00', '2026-09-07 07:29:12.865062+00', '2026-09-07 07:29:53.437631+00', NULL, '', '2', '', '1', '100000794', NULL, '这是一份由四川欣联鑫新能源有限公司出具的文件，标题为“附件1：主要材料清单”。文件主体是一张表格，列出了光伏发电项目所需的主要材料及其标准、品牌和材质，包括：通威550W及以上单晶组件、华为逆变器和GRPS模块、国标铜芯直流/交流电缆、热镀锌C型钢及支架、铝合金压扣夹具、304不锈钢螺丝、浙江欧惠MC4端子、昌松电力防孤岛及防雷装置、接地扁铁以及其他辅助材料等。文件上盖有红色公章，页码为第7页。', '0', 'ready', '', ''),
