该文档是国网重庆市电力公司出具的一份电费账单，缴费对象为重庆星达铜业有限公司（户号5001654065328），账单周期为2026年8月1日至8月31日，账单打印日期为2026年9月4日，交费截止日期为2026年9月9日。该户用电类别为大工业用电，电压等级为交流10千伏，市场化属性为市场化零售客户，由璧城供电服务中心供电，用电地址位于重庆市璧山区青杠街道莲花社区。
账单显示，本期总电量为555,617千瓦时，环比下降15.18%；总电费393,459.72元，平均电价0.70815元/千瓦时，较上期减少0.01151元/千瓦时。电费主要由三部分构成：一是工商业电费391,579.91元（计费电量547,287千瓦时），包含市场化购电费213,339.58元、上网环节线损费用9,453.84元、输配电费111,051元、系统运行费31,633.19元及政府性基金及附加26,102.3元，其中零售交易电费按0.436元/千瓦时计收，并含中长期偏差回收返还-39,397.7元等返还项目；二是居民电费4,414.9元，按定比0.015计提8,330千瓦时，执行居民生活合表用电电价；三是功率因数调整电费-2,535.09元。
