这是一份由国网重庆市电力公司出具的电费账单，账单周期为2026年8月1日至8月31日，账单打印日期为2026年9月4日，交费截止日期为2026年9月9日。账单对象为重庆星达铜业有限公司（户号5001654065328），用电类别为大工业用电，电压等级为交流10kV，属市场化零售客户，供电服务单位为璧城供电服务中心，用电地址位于重庆市璧山区青杠街道。
本期总电量为555617千瓦时，总电费为393459.72元。费用主要由工商业电费和居民电费两部分构成：工商业电量547287千瓦时，电费391579.91元，包含市场化购电费213339.58元（其中零售交易电费238617.14元，另有零售损益分摊、中长期偏差回收返还等多项退减费用）、上网环节线损费用9453.84元、输配电费111051元（含容量电费44000元，容量2000千伏安）、系统运行费31633.19元（涵盖煤电、燃气机组及抽水蓄能容量电费、新能源机制差价分摊等）以及政府性基金及附加26102.3元；居民电量8330千瓦时（按定比0.015计提），电费4414.9元。此外，因实际功率因数0.97高于0.90的标准，功率因数调整电费为-2535.09元。
用能分析显示，本期电量环比下降15.18%；尖峰平谷分时比例分别为2.55%、16.68%、30.45%、50.32%，与上期基本持平（账单附有柱状对比图佐证）；实际功率因数0.97与上期持平；平均电价为0.70815元/千瓦时，较上期下降0.01151元/千瓦时。
账单详情部分列出了电能表（编号5030001221300052554525）的正向有功分时电量明细及各项费用的计费电量、计费标准与金额，并附有峰谷时段划分说明、两部制用户容（需）量电费选择规则等备注信息，同时提示用户可通过扫描二维码登录网上国网App查询电价公示表和账单详情。', '9', 't', '0', '0', '', '', 'summary', '87b202d9-1ce0-447b-b952-ff9c6dd6d2c9', '', NULL, NULL, '2026-09-09 08:42:15.668359+00', '2026-09-09 08:42:15.668359+00', NULL, NULL, '', '0', '', '1', '100001042', NULL, '# Summary
